import java.util.*;
import java.io.*;

public class Main {
    static int[] findOrder(int n, int[][] pairs) {
        // Write your solution here
        // Return the lexicographically smallest valid order, or an empty array if none exists.
        return new int[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[][] pairs = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken(); pairs[i][0] = (int) in.nval;
            in.nextToken(); pairs[i][1] = (int) in.nval;
        }
        int[] order = findOrder(n, pairs);
        if (order.length == 0) {
            System.out.println(-1);
            return;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < order.length; i++) sb.append(order[i]).append(i + 1 < order.length ? " " : "\n");
        System.out.print(sb);
    }
}
